export function installRoadSurface(material){material.onBeforeCompile=shader=>{shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nattribute float roadSurface; varying float vRoadSurface; varying vec3 vRoadPosition;').replace('#include <begin_vertex>','#include <begin_vertex>\nvRoadSurface=roadSurface;vRoadPosition=position;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying float vRoadSurface;varying vec3 vRoadPosition;').replace('#include <color_fragment>',`#include <color_fragment>
vec2 rp=vRoadPosition.xz;float vis=1.-smoothstep(.1,.6,max(fwidth(rp.x),fwidth(rp.y)));
float tex=1.;if(vRoadSurface>.5&&vRoadSurface<1.5){vec2 tile=fract(vec2(rp.x*2.+floor(rp.y*3.)*.5,rp.y*3.));tex=mix(.72,1.,step(.05,tile.x)*step(.07,tile.y));}else{float noise=fract(sin(dot(floor(rp*5.),vec2(127.1,311.7)))*43758.5453);tex=.88+noise*.18;}diffuseColor.rgb*=mix(1.,tex,vis);`);};material.customProgramCacheKey=()=> 'chisinau-road-surfaces-v1';}
